#!/bin/sh
# SPEC 502.gcc_r train: arms plain-rv64 in that order, each in a fresh copy of in/ under /tmp/sr.
# Generated by capstone/ports/spec-cpu2017/board/make-stage.py from runcpu's own command files.
S=$(cd "$(dirname "$0")" && pwd)
V=${SPEC_VEXEC:?set SPEC_VEXEC to the batch launcher}
export CAPSTONE_VM_STATS=1
n=0
gtsnap() { echo "@@GT-SNAP$1 $2 hpm=$(cat /sys/module/capstone_vm/parameters/hpm_snapshot 2>/dev/null || echo NA) vm=$(grep -E '^(pgfault|pgmajfault|pgalloc_normal|pgfree|pgactivate|nr_free_pages) ' /proc/vmstat | tr ' \n' ':,') st=$(grep -E '^(ctxt|processes|intr) ' /proc/stat | cut -d' ' -f1-2 | tr ' \n' ':,') mem=$(grep -E '^(MemFree|MemAvailable):' /proc/meminfo | tr -s ' ' | tr ' \n' ':,')"; }
bench() { dmesg | grep 'capstone_vm: bench' | tail -1 | sed 's/.*capstone_vm: //'; }
nbench() { dmesg | grep -c 'capstone_vm: bench'; }
up() { cut -d' ' -f1 /proc/uptime; }
# the module's cumulative in-context counters (sysfs, 0444): their delta over a command sums every context it ran
sysb() { for f in cycles instret entries; do cat /sys/module/capstone_vm/parameters/bench_$f 2>/dev/null || echo 0; done | tr '\n' ' '; }
echo "@@SPEC-STAGE 502.gcc_r train arms=plain-rv64 commands=1 validations=0"
echo "@@SPEC-ARM-BEGIN plain-rv64"
cd / && rm -rf /tmp/sr && mkdir -p /tmp/sr && cp -a "$S/in/." /tmp/sr/ && cd /tmp/sr || exit 1
echo "@@SPEC-BEGIN $n run plain-rv64 0"
k0=$("$S/rdctr")
u0=$(up)
gtsnap 0 $n
"$S/ru" "$S/bin/plain-rv64/cpugcc_r_base.plain-rv64" train01.c -O3 -finline-limit=50000 -o train01.opts-O3_-finline-limit_50000.s > train01.opts-O3_-finline-limit_50000.out 2>> train01.opts-O3_-finline-limit_50000.err
rc=$?
gtsnap 1 $n
echo "@@GT-RU $n $(cat /tmp/ru.log 2>/dev/null)"; rm -f /tmp/ru.log
u1=$(up)
k1=$("$S/rdctr")
echo "@@SPEC-CTR $n plain-rv64 $k0 $k1"
echo "@@SPEC-END $n run plain-rv64 0 rc=$rc up0=$u0 up1=$u1 nbench=0 :: plain"
n=$((n+1))
echo "@@SPEC-HASH-BEGIN plain-rv64"
find . -type f | sort | while read -r f; do sha256sum "$f"; done
echo "@@SPEC-HASH-END plain-rv64"
if [ -f train01.opts-O3_-finline-limit_50000.err ] && [ $(wc -c < train01.opts-O3_-finline-limit_50000.err) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE plain-rv64 train01.opts-O3_-finline-limit_50000.err"; gzip -9c train01.opts-O3_-finline-limit_50000.err | base64; echo "@@SPEC-FILE-END"; fi
if [ -f train01.opts-O3_-finline-limit_50000.out ] && [ $(wc -c < train01.opts-O3_-finline-limit_50000.out) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE plain-rv64 train01.opts-O3_-finline-limit_50000.out"; gzip -9c train01.opts-O3_-finline-limit_50000.out | base64; echo "@@SPEC-FILE-END"; fi
if [ -f train01.opts-O3_-finline-limit_50000.s ] && [ $(wc -c < train01.opts-O3_-finline-limit_50000.s) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE plain-rv64 train01.opts-O3_-finline-limit_50000.s"; gzip -9c train01.opts-O3_-finline-limit_50000.s | base64; echo "@@SPEC-FILE-END"; fi
echo "@@SPEC-ARM-END plain-rv64"
cd / && rm -rf /tmp/sr /tmp/sw
echo "@@SPEC-DONE 502.gcc_r train"
